/* Scottish Gaelic Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Hamish": "The beloved Gaelic form of James.", "Mhairi": "The Gaelic form of Mary, pronounced VAR-ee.", "Alasdair": "defender of men — Greek Alexandros, via Gaelic", "Catriona": "pure — Greek Katherine, via Gaelic", "Ewan": "born of the yew — Gaelic Eoghan", "Ishbel": "The Gaelic form of Isabel.", "MacDonald": "The great clan of the Lords of the Isles.", "MacLeod": "The great clan of Skye.", "Campbell": "The great Argyll clan.", "MacKenzie": "The great Ross-shire clan."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Hamish';
console.log(lookup(q));

